-- Auto-generated by scripts/curriculum/build-level-sql.mjs -- do not
-- hand-edit the lesson content below; regenerate from the source plan
-- JSON instead if something needs to change.

do $$
declare
  v_course_id uuid := 'e1cf8de5-53fd-4745-842e-5b98f90d3073';
  v_level uuid;
  -- modules.order_number is unique per COURSE, not per level (a course's
  -- modules are numbered continuously across all its levels) -- so this
  -- can't just start at 1 for a level beyond the first. Computed here
  -- instead of hardcoded so this script works correctly regardless of how
  -- many modules the course already has.
  v_module_offset int;
  v_m1 uuid;
  v_m2 uuid;
begin
  -- Appending to a level that already exists. Looked up rather than
  -- inserted, so this adds to the learner's current Level 1 instead of
  -- creating a duplicate one, and no existing module is re-parented.
  select id into v_level from public.levels
    where course_id = v_course_id and order_number = 1;

  if v_level is null then
    raise exception 'Level % not found for course % -- refusing to guess', 1, v_course_id;
  end if;

  -- The new modules must sit INSIDE this level, not at the end of the
  -- course. getOrderedLessons() builds the learner's lesson sequence from
  -- modules.order_number alone and ignores level, so a module appended at
  -- the course's max order would put beginner content after the final
  -- level's material. Insert straight after this level's last module and
  -- shift everything below it down instead.
  select coalesce(max(order_number), 0) into v_module_offset
    from public.modules where level_id = v_level;

  -- Two-phase shift: (course_id, order_number) is unique, and a single
  -- "+ N" update can trip that constraint mid-statement, so park the rows
  -- out of range first and bring them back afterwards.
  update public.modules set order_number = order_number + 1000
   where course_id = v_course_id and order_number > v_module_offset;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Saving Before You Spend', 'The existing lessons explain what a budget is and how mobile money works. This one is about the habit that decides whether a budget ever produces anything — and the force that makes small amounts matter.', v_module_offset + 1)
  returning id into v_m1;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m1, 'Paying Yourself First', 'Khan Academy on the one budgeting habit that works: taking savings out first rather than saving whatever survives the month. About 4 minutes.', 'https://www.youtube.com/watch?v=k-RTEIaYvAg', 1,
      array['Set aside savings at the start of the month rather than the end', 'Choose an amount you can sustain rather than an ambitious one', 'Separate saved money from spending money so it is harder to reach'],
      'Almost everyone who fails to save is doing the same thing: spending first and intending to save whatever is left. There is never anything left. That is not a discipline failure — it is an ordering failure, and reversing the order fixes it.

PAY YOURSELF FIRST means the moment money arrives, a fixed amount moves to savings BEFORE any spending. You then live on the rest. The amount that reaches your savings stops depending on how the month went.

START SMALLER THAN FEELS SERIOUS. Someone earning irregular income who commits to saving half will break the habit in week two and feel like a failure. A hundred shillings a week, sustained for a year, beats an ambitious plan abandoned in February — because what you are building first is the habit, and only later the balance.

MAKE IT AUTOMATIC AND MAKE IT AWKWARD TO REVERSE. Money that sits in the same place you spend from will be spent. Practical options here include a separate account, an M-Shwari or KCB M-Pesa lock savings account with a fixed term, a SACCO where withdrawal takes deliberate effort, or a chama with people who will notice if you skip. The friction is the feature.

IF YOUR INCOME IS IRREGULAR, and for freelancers and small traders it usually is, save a PERCENTAGE rather than a fixed amount. Ten per cent of whatever comes in, every time it comes in, adapts automatically to a good month and a bad one. Decide the percentage once, then stop deciding.

SAVE FOR SOMETHING NAMED. "Savings" is easy to raid. "School fees, January" or "laptop for work" is much harder, because spending it means admitting what you are giving up.

AND EXPECT TO BE ASKED FOR IT. In many Kenyan families, visible savings attract requests, and refusing is genuinely difficult. This is a real reason people keep money where it is easy to spend rather than easy to protect. Deciding in advance what you will say — and keeping some savings in a form that is not instantly accessible — is a practical part of the skill, not a personal failing.',
      'Work out one number: what could you move to savings the moment money arrives, in a month that goes badly? Not your best month — your worst. Then set it up so it happens without you: a standing instruction, a lock savings account, or a fixed transfer you make the same day you get paid. Name the goal. Then leave it alone for one month and check whether the amount was sustainable; adjust once, and only downward if it was not.',
      '[{"question":"What does paying yourself first actually mean?","options":["Moving a set amount to savings as soon as money arrives, before any spending","Spending on yourself before paying bills","Saving whatever is left at the end of the month","Paying off your most expensive debt first"],"correct_index":0},{"question":"Why should someone with irregular income save a percentage rather than a fixed amount?","options":["It adapts on its own to good months and bad ones, so the habit survives","Percentages earn more interest","Fixed amounts are not allowed by most savings accounts","It removes the need to budget at all"],"correct_index":0}]'::jsonb),
    (v_m1, 'Compound Interest: the Force Working For or Against You', 'Khan Academy on how compound interest works — the mathematics behind both growing savings and debt that gets out of hand. Under 7 minutes.', 'https://www.youtube.com/watch?v=Rm6UdfRs3gw', 2,
      array['Explain the difference between simple and compound interest', 'Work out what an interest rate actually costs or earns over time', 'Convert a small periodic rate into its yearly equivalent'],
      'This is the most important piece of arithmetic in personal finance, and it cuts both ways: it is what makes saving worthwhile over years, and what makes borrowing dangerous over months.

SIMPLE INTEREST is charged on the original amount only. COMPOUND INTEREST is charged on the original amount PLUS the interest already added. The second grows far faster, and the more often it compounds — yearly, monthly, weekly — the faster it goes.

THE SKILL THAT PROTECTS YOU: converting a small-sounding rate into a yearly one. A charge of "just 7.5% per month" is not 7.5% a year. Compounded monthly it is roughly 138% a year. A fee of 1% a week is not 52% a year — compounded, it is about 68%. Small periodic numbers hide very large annual ones, and lenders quote the small number for exactly that reason.

SO ALWAYS ASK TWO QUESTIONS before borrowing anything: what is the total amount I will repay, in shillings, and what is that as a yearly rate? A lender who cannot or will not tell you the first is one to walk away from. Kenyan law requires disclosure of borrowing costs, and the Central Bank of Kenya publishes a list of licensed digital lenders — checking it takes a minute and unlicensed apps are where the worst practices live.

THE SAME FORCE ON YOUR SIDE: money saved earns interest, and that interest earns interest. Over a year the difference is unexciting. Over ten it is the difference between having capital and not. This is why starting small at 22 beats starting seriously at 35 — the early money has more time to compound, and time is the input you cannot buy back.

A REALISTIC NOTE ON RATES: ordinary Kenyan savings accounts pay very little, and inflation can outrun them, so cash sitting still slowly loses buying power. SACCOs and money market funds have historically paid more, with correspondingly more to understand before committing. Nothing in this lesson is advice about a specific product — the skill being taught is checking the real yearly number yourself before you agree to anything, whether you are lending or borrowing.',
      'Take a real loan offer you have seen — a mobile app, a shop instalment plan, a friend''s arrangement — and calculate two things: the total shillings repaid versus borrowed, and the approximate annual rate. Then do the reverse: work out what saving your paying-yourself-first amount every month for five years would total, ignoring interest, then look up what a SACCO or money market fund would have added. Write both numbers down. The gap between them is what this lesson is for.',
      '[{"question":"A lender charges 7.5% per month. Roughly what is that as a yearly rate, compounded?","options":["About 138% — small periodic rates hide very large annual ones","7.5%, since the rate does not change","90%, which is 7.5 multiplied by 12","It cannot be converted to a yearly figure"],"correct_index":0},{"question":"Why does starting to save small at 22 beat starting seriously at 35?","options":["The early money has far more time to compound, and time cannot be bought back","Interest rates are higher for younger savers","Banks reward long-standing customers with better terms","Smaller amounts are taxed less"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Debt, and What It Really Costs', 'Borrowing is not automatically a mistake — it is a tool with a price. This module is about reading that price before you agree to it, which is exactly what the products designed to catch you rely on you not doing.', v_module_offset + 2)
  returning id into v_m2;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m2, 'What Debt Is and When It Makes Sense', 'Khan Academy on debt and loans — what borrowing actually is, and how to think about whether a particular loan is worth taking. Under 5 minutes.', 'https://www.youtube.com/watch?v=MFCdA2vGVh4', 1,
      array['Distinguish borrowing that builds something from borrowing that consumes', 'Read the real terms of a loan before agreeing to it', 'Recognise when repayments have become unmanageable'],
      'Debt is renting money. Like renting anything, it can be sensible or wasteful depending on what you do with it and what you pay.

BORROWING THAT CAN MAKE SENSE buys something that earns or saves more than the loan costs: stock for a business that sells at a margin, a tool that lets you take paid work, training that raises what you can charge. The test is whether the thing you buy produces more than the interest.

BORROWING THAT RARELY MAKES SENSE covers ordinary consumption — a night out, clothes, airtime, a phone you cannot afford. The purchase is over and the repayments are not.

THE EMERGENCY CASE is real and different. Sometimes there is no good option, only a least-bad one. That is precisely what an emergency fund exists to prevent, and why the previous module comes first.

WHAT TO ESTABLISH BEFORE YOU AGREE, every time:
- The TOTAL you will repay, in shillings
- Every FEE, including processing, late payment and rollover charges — fees are often where the real cost sits
- The repayment DATE and what happens if you miss it
- Whether it is reported to a credit reference bureau

THAT LAST ONE MATTERS MORE THAN PEOPLE REALISE HERE. Defaulting on even a small mobile loan can be reported to a CRB and follow you for years, affecting later borrowing for a business or a house. A KSh 500 loan forgotten about is a genuinely disproportionate way to damage your record.

WARNING SIGNS THAT DEBT HAS BECOME THE PROBLEM RATHER THAN A TOOL: borrowing from one place to repay another, taking a new loan the same day you clear one, or not knowing the total you owe. If any of those is true, stop borrowing before doing anything else, write down every debt with its true cost, and pay the most expensive first.

AND TALK TO THE LENDER BEFORE YOU MISS A PAYMENT rather than after. A person who calls ahead is far more likely to be given time than one who goes silent.',
      'List every debt you currently have — including money owed to family, which people leave off. For each, write the amount, the total repayable, the due date and whether it is reported to a CRB. Add them up; most people find the total is larger than they thought. Then order them by true cost and mark which single one you will clear first.',
      '[{"question":"What is the test for whether borrowing makes sense?","options":["Whether the thing you buy produces more than the interest costs","Whether the monthly repayment fits your income","Whether the lender is well known","Whether the amount is small"],"correct_index":0},{"question":"Which pattern means debt has stopped being a tool?","options":["Borrowing from one place to repay another","Having more than one loan at a time","Borrowing to buy stock for a business","Repaying early"],"correct_index":0}]'::jsonb),
    (v_m2, 'Payday and Instant Loans: How the Trap Works', 'Khan Academy on payday loans — worked through with real numbers, showing how a short-term loan becomes a long-term problem. About 10 minutes.', 'https://www.youtube.com/watch?v=BHTMuHvmarU', 2,
      array['Calculate the true annual cost of a short-term loan', 'Explain the rollover cycle and why it is hard to escape', 'Identify safer alternatives before an emergency happens'],
      'This video uses American payday lenders, and the structure it describes is exactly the structure of instant mobile lending — which is why it is here rather than a local video. The mechanism transfers completely; only the names change.

HOW THE TRAP IS BUILT: a small amount, available instantly, with a fee that sounds trivial. The fee is charged per short period. Repayment is due in days or weeks, in full. If you cannot repay, you roll it over — and pay the fee again.

WHY THAT IS SO EXPENSIVE: a fee that reads as a small percentage over one week becomes an enormous annual rate once it repeats. That is not a criticism of any particular company; it is arithmetic, and it is why the previous lesson taught you to convert the small number into the yearly one.

THE CYCLE IS THE PRODUCT. These loans are not designed around the person who borrows once and repays on time. The revenue comes from repeat borrowing and rollover. Once you are in the cycle, each repayment leaves you short again, which produces the next loan.

IN THE KENYAN CONTEXT this arrives as instant lending apps and overdraft facilities on mobile money — borrow in seconds, repay in days, fees stated per period. Some are licensed by the Central Bank of Kenya and some are not; the CBK publishes the list of licensed digital credit providers, and checking it before you install anything is a genuinely useful two minutes. Unlicensed apps are where the aggressive collection practices and contact-list harassment have been reported.

BEFORE YOU BORROW THIS WAY, work through the alternatives honestly: a SACCO loan if you are a member, a chama, an advance from an employer, family, selling something, or negotiating more time from whoever you owe. All of these are slower and all of them are cheaper. "Instant" is the feature you are paying for.

AND THE REAL ANSWER IS UPSTREAM: the emergency fund from the first module in this level. Money set aside before the emergency is what makes it possible to say no to a loan that costs three figures a year. That is the whole point of the ordering in this course — save first, so you are never negotiating from desperation.

IF YOU ARE ALREADY IN THE CYCLE: stop taking new loans, write down every one, pay the most expensive first while paying minimums on the rest, and talk to the lenders before you default rather than after.',
      'Find one instant loan product you or someone you know has used. Write down the amount borrowed, every fee, the repayment period, and the total repaid. Convert it to an annual rate. Then check whether that provider appears on the Central Bank of Kenya''s list of licensed digital credit providers. Finally, write the three alternatives you would use instead next time — decided now, while you are not under pressure.',
      '[{"question":"Where does the revenue in short-term instant lending mostly come from?","options":["Repeat borrowing and rollover, not from people who borrow once and repay on time","The initial processing fee","Interest earned over the full year of the loan","Penalties from defaulted loans"],"correct_index":0},{"question":"What is the upstream fix that removes the need for these loans?","options":["An emergency fund saved before the emergency, so you are not negotiating from desperation","Borrowing a larger amount to cover more months","Using several lenders so no single debt is large","Choosing the app with the lowest weekly fee"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  -- Bring the shifted modules back, now sitting after the 2 new one(s).
  update public.modules set order_number = order_number - 1000 + 2
   where course_id = v_course_id and order_number > 1000;

end $$;
